SELECT f.id, cl.nome AS cliente, f.nome, f.versao, f.status, COUNT(DISTINCT cr.id) AS criterios
  FROM formularios f
  JOIN clientes cl ON cl.id = f.cliente_id
  LEFT JOIN formulario_secoes s ON s.formulario_id = f.id
  LEFT JOIN formulario_criterios cr ON cr.secao_id = s.id
 WHERE f.nome IN (
   'Empresarial - Cobrança',
   'Receptivo - Educacional - Empresarial',
   'Yduqs',
   'IA FIRJAN >>> TELEFONE RECEPTIVO',
   'FIRJAN >>> Formulário de monitoria TELEFONE RECEPTIVO',
   'Formulário CEDAE - Cobrança',
   'Formulário FIESP - Cobrança',
   'Vero B2B',
   'Avaliação de atendimento Vero - SP - Churn',
   'Grupo Avenida',
   'Avaliação atendimento vero SP',
   'Avaliação de atendimento Vero - SP - IA - Churn',
   'Avaliação de atendimento Vero - SP - IA - Pré Churn',
   'Avaliação de atendimento Vero Ativo IA',
   'Avaliação de atendimento Vero - SP - Pré Churn',
   'Avaliação de atendimento Vero - SP - Ativo',
   'Formulário Educacional | Receptivo',
   'Formulário Educacional | Cruzeiro',
   'Formulário Yduqs',
   'FIERGS - Formulário de Monitoria TELEFONE ATIVO - Informativa e Prospecção',
   'Cobrança - ISAAC - Cópia - IA - Cópia',
   'Cobrança - ISAAC',
   'Formulário ISAAC - IA',
   'Formulário - Cruzeiro do Sul',
   'Ânima',
   'FIRJAN >>> Formulário de Monitoria TELEFONE ATIVO - Informativa e Prospecção - IA',
   'FIRJAN >>> Formulário de Monitoria TELEFONE ATIVO - Informativa e Prospecção',
   'FIRJAN >>> Formulário de monitoria ONLINE (CHAT - WhatsApp - Redes Sociais)',
   'FIRJAN >>> Formulário de monitoria E-MAIL',
   'Avaliação cobrança Educacional - IA',
   'FIRJAN >>> Formulário de monitoria SAÚDE DIGITAL',
   'FIRJAN >>> Formulário WhatsApp MASSAGEM RELAXANTE CRS',
   'FIRJAN >>> Formulário WhatsApp ODONTO CRS'
 )
 GROUP BY f.id, cl.nome, f.nome, f.versao, f.status
 ORDER BY cl.nome, f.nome, f.versao;
