INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Condução do atendimento', 'Conduziu, organizou e explicou corretamente as informações, garantindo clareza, coerência, objetividade e alinhamento. / Informou que caso a ligação caia, irá retornar o contato prontamente', 10.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificou se o cliente tem algum relacionamento com a empresa', 'Questionou se o cliente trabalha em alguma empresa do ramo da indústria e/ou é associada a um dos sindicatos filiados. Se sim, informe que caso comprove o vínculo no balcão de atendimento poderá usufruir de valores diferenciados.', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificação de oportunidades', 'Oferecimento do curso solicitado em outras localidades caso não esteja disponível na unidade que o cliente sinalizou interesse / Oferecimento de outros cursos na mesma área solicitada pelo cliente.', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Realizou sondagem adequada.', 'Não realizou sondagem adequada e necessária para investigar o que o cliente deseja, e não entendeu sua real necessidade.', 10.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Empatia e Relacionamento com o Cliente', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ausência prolongada e retorno injustificados', 'Solicitou e justificou o momento solicitado/Agradeceu ao retornar/Ultrapassou mais de 1 minuto para retornar ao cliente.', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Personalizou o atendimento', 'Chamou o cliente pelo nome no mínimo 3 vezes durante o atendimento', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Demonstrou cordialidade durante o atendimento', 'Utilizou expressões de cordialidade durante a comunicação (obrigado(a), por gentileza, por favor e etc), demonstrou empatia e gentileza.', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Linguagem inadequada', 'Gírias e vícios de Linguagem (tá, ok, né, hum-hum, no caso ou outras expressões repetidas) / Verbos no condicional (gostaria, seria, poderia), uso do diminutivo / Evitou termos técnicos que são de conhecimento interno (regimental, PFO, nomenclatura, módulos, comunidade) / Palavras ou expressões negativas (infelizmente, problema, dúvida, demora, etc.) / Gerundismo (vamos estar enviando, vou estar fazendo, vou estar registrando) / Pronúncia e concordância', 5.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Erros de digitação no registro', 'Cometeu erros de digitação no registro (concordância, pontuação e etc)', 5.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro incompleto e/ou incorreto / Tabulação incompleta e/ou incorreta', 'Registrou ou tabulou o atendimento de forma incompleta e/ou incorreta.', 10.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Encerramento do Atendimento', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Questionou se o cliente ficou com alguma dúvida ao final do atendimento.', 'Questionou se o cliente ficou com alguma dúvida ao final do atendimento (Algo mais em que posso ajudar?), (Ficou alguma dúvida?)', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Utilizou saudação final', 'Utilizou fraseologia de finalização: A Firjan agradece, tenha um excelente e/ou ótimo dia/tarde/noite.', 5.00, 0, 2);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Erros Críticos (NCG)', NULL, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Pesquisa de satisfação', 'Não encaminhou o cliente para a pesquisa de satisfação ao final do atendimento / Cometeu erros de digitação ou escrita, endereço e etc, no envio do e-mail ao cliente. / Não enviou a pesquisa de satisfação por e-mail ao final do atendimento.', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificou a necessidade do cliente', 'Não realizou sondagem adequada e necessária para investigar o que o cliente deseja, e não entendeu sua real necessidade (caso gere algum prejuízo para o cliente)', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas/Incorretas', 'Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitir informações relevantes que podem prejudicar o cliente ou gerar uma re-chamada. / Transmitiu informação equivocada ou que não conste em nossos documentos.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Classificação do ticket de atendimento', 'Não classificou o ticket do atendimento de forma completa e correta.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro do atendimento', 'Não registrou o atendimento (Criou caso)', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Entonação', 'Utilizou palavras de baixo calão, tom de voz irônico, ríspido, demonstrou ausência de atenção total e/ou impaciência. / Utilizou frases “como já havia dito anteriormente”, "então" e etc', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificação de oportunidades', 'Não divulgou informações das campanhas vigentes, informando sobre matricula / inscrição, contribuindo diretamente para o resultado da organização.', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão do atendimento (Indisponibilidade)', 'Não atendeu a necessidade do cliente / Encerrou a ligação sem finalizar o atendimento / Não atendeu ao cliente / Não prestou o atendimento, quando tinha acesso as informações e etc', NULL, 1, 8);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prestou as informações completas e corretas sobre a Campanha Vigente', 'Prestou as informações completas e corretas sobre a Campanha Vigente', NULL, 1, 9);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
INSERT INTO formularios (cliente_id, nome, descricao, categoria, tipo_calculo, status, versao)
INSERT INTO campanhas (cliente_id, nome, canal, ativa) VALUES (@cliente_id, @campanha_nome, 'chat', 1) ON DUPLICATE KEY UPDATE canal=VALUES(canal), ativa=1;
INSERT IGNORE INTO formulario_campanhas (formulario_id, campanha_id) VALUES (@formulario_id, @campanha_id);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'ABERTURA (peso 20)', NULL, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prontidão', 'Iniciou o atendimento em até 5s.', 8.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação Inicial', 'Identificou-se como sou representante da Light, Datora, Vero, Truly Nolem, Sicoon, Hy plataforma, Norte Saneamento. Ex.: ATIVO: (primeiro nome) José ! Bom Dia! Meu nome é ______ sou da assessoria financeira xxx)', 6.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação Final', 'Finalizou o contato de forma respeitosa e se necessário seguindo o roteiro de atendimento padrão,.', 6.00, 0, 3);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'DESENVOLVIMENTO (peso 30)', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Comunicação de Ausência / Tempo de Espera', 'Comunicou que iria se ausentar, informando ao cliente que poderia chamá-lo a qualquer momento? Neste contexto não abandonou o contato por demasia deixando um vácuo na ligação', 10.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Realização / Atualização do Cadastro', 'Perguntou se o e-mail e/ou telefone foram alterados para envio do boleto? Caso cadastro não tenha e-mail preenchido, solicitou este dado para envio do boleto?', 10.00, 0, 2);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NEGOCIAÇÃO / COBRANÇA (peso 50)', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Abordagem', 'Apresentou, conforme o roteiro, o motivo do contato, informando os valores da proposta, os débitos incluídos na negociação e a data de pagamento disponível na plataforma, destacando a condição como uma oportunidade.', 15.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Sondagem (estrutura da pergunta)', 'Levantar informações relevantes para direcionar a negociação, utilizando perguntas claras, abertas e estratégicas. Ex: “Existe alguma previsão para regularização desse débito?” ''''Qual seria a melhor data ou formato para viabilizar esse acordo?''''', 15.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Fechamento da negociação', 'Acordo realizado: Reforçou a importância do pagamento do acordo dentro do vencimento, informando que a inadimplência pode gerar cancelamento do acordo, cobrança de juros e multa, além da inclusão do CPF em órgãos de proteção ao crédito, com possíveis prejuízos financeiros ao cliente. Recusa: Orientar o cliente quanto às consequências da manutenção do débito em aberto, incluindo a incidência de juros e multas, a possibilidade de ligações recorrentes para cobrança e a eventual negativação do CPF junto aos órgãos de proteção ao crédito.', 20.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Contorno de objeção', 'Baseando-se nas objeções impostas por nosso aluno, o agente fez no mínimo 03 contornos durante o contato? (Neste contexto, será avaliado se agente apenas cumpriu protocolo ou fez um contorno coerente a ligação).', 10.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NCG - Não Conformidade Grave', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações erradas', 'Passou informação incorreta ao cliente, divergente do roteiro ou ferramentas de suporte. Erro operacional na orientação ou procedimento informado.', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas', 'Não cumprimento integral do checklist ou roteiro de atendimento. Falta de registro ou execução de etapas obrigatórias (ex: cadastro CPC). Aplicável quando a ausência da informação pode gerar prejuízo ao processo ou às partes envolvidas.', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Acordo indevido', 'Fechamento de negociação sem confirmação do devedor. Registro incorreto ou inadequado do acordo realizado. Possível indício de falha grave ou má condução do processo.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Tabulação (registro do atendimento)', 'Registro incorreto ou ausência de tabulação do motivo do contato. Falha no lançamento do atendimento no sistema.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Quebra de sigilo', 'Divulgação indevida de informações a terceiros sem autorização. Falha na confirmação de dados conforme diretrizes da LGPD.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Desconexão da chamada (derrubar ligação)', 'Encerramento da ligação sem justificativa válida.', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão do atendimento', 'Ligações identificadas como caixa postal e o operador não encerrou de imediato, deixando a ligação em curso.', NULL, 1, 7);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
INSERT INTO formularios (cliente_id, nome, descricao, categoria, tipo_calculo, status, versao)
INSERT INTO campanhas (cliente_id, nome, canal, ativa) VALUES (@cliente_id, @campanha_nome, 'chat', 1) ON DUPLICATE KEY UPDATE canal=VALUES(canal), ativa=1;
INSERT IGNORE INTO formulario_campanhas (formulario_id, campanha_id) VALUES (@formulario_id, @campanha_id);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'ABERTURA', 'Avaliação da abertura do atendimento, com foco na abordagem inicial, identificação do cliente e clareza na comunicação, garantindo um início cordial, profissional e alinhado aos padrões estabelecidos.', 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prontidão', 'Interagiu em até 5 (cinco) segundos após o início do contato.', 6.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação inicial', 'O operador informou sua identificação, apresentando-se como representante da área financeira SESI/SENAI, FIESP equivalente, deixando claro o motivo institucional do contato. (Ex.: Olá! bom dia, falo em nome da Fiesp, Sesi e Senai. Me chamo (nome do Atendente), falo com o Sr(a). (nome completo do cliente) inscrito no CPF (000.000.000-00)?', 2.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Personalização', 'Chamou o cliente pelo nome ao menos 2 vezes, garantindo uma experiência acolhedora, humanizada e alinhada às suas necessidades.', 1.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Vícios de Linguagem / Erros de Português', 'Avaliação de vícios de linguagem e erros de português, considerando a clareza, correção e fluidez na comunicação. Atenção: a partir de 3 ocorrências de vícios de linguagem, o critério passa a ser considerado não conforme. Comunicou-se sem falar erro grave de português como: plural, concordância, pronúncia...?', 10.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Dicção - Tom de voz', 'Considerando clareza na fala, ritmo adequado e entonação, garantindo uma comunicação compreensível, segura e alinhada a um atendimento acolhedor e profissional.', 8.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Empatia', 'Considerando a capacidade de compreender a situação do cliente, demonstrar acolhimento e conduzir a interação com respeito e sensibilidade, garantindo uma experiência mais humana e positiva.', 5.00, 0, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Condução - Escuta ativa', 'Avaliação da condução e escuta ativa, considerando a capacidade de ouvir atentamente, compreender a real necessidade do cliente e conduzir o atendimento de forma clara, organizada e assertiva, garantindo uma interação fluida e focada na solução.', 1.00, 0, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação Final', 'Considerando o encerramento cordial, a disponibilidade para novas orientações e a finalização clara do atendimento.', 2.00, 0, 8);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'DESENVOLVIMENTO', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Comunicação de Ausência / Tempo Excedente em Espera', 'Avaliação da comunicação de ausência ou tempo excedente em espera, considerando se o cliente é informado de forma clara e adequada sobre pausas, retornos e possíveis demoras, garantindo transparência e uma experiência mais segura durante o atendimento.', 1.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Domínio e Segurança', 'Considerando o conhecimento do atendente sobre os processos, clareza nas informações e confiança na condução do atendimento, garantindo assertividade e credibilidade na comunicação com o aluno.', 1.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Atualização cadastral', 'Realização e atualização do cadastro, considerando a coleta e validação correta dos dados do cliente, bem como a atualização adequada das informações em sistema.', 2.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Autoatendimento', 'Avaliação do direcionamento ao autoatendimento, considerando se o atendente informou, quando aplicável, sobre os canais disponíveis da IES (Portal do Aluno/Giz, Meu Arco), incentivando a autonomia do aluno e facilitando futuras consultas e solicitações.', 1.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NEGOCIAÇÃO/COBRANÇA', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Abordagem', 'Avaliação da apresentação do motivo do contato, considerando se o atendente seguiu o roteiro ao expor a proposta, informando de forma clara os valores, débitos incluídos na negociação, forma de pagamento a vista, pix, parcelado e a data de pagamento disponível na plataforma, utilizando comunicação estratégica para valorizar a oportunidade de regularização.', 12.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Sondagem', 'Avaliação da sondagem, considerando a capacidade do atendente de compreender o cenário do cliente após apresentar o motivo do contato e a proposta, explorando de forma estratégica as necessidades e possibilidades, a fim de direcionar a negociação de maneira mais assertiva.', 12.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Argumentação', 'Avaliação da argumentação, considerando a capacidade do atendente de utilizar o discurso do cliente para construir colocações pertinentes, destacando características e benefícios da proposta, com o objetivo de conduzir o atendimento de forma estratégica rumo ao aceite da negociação.', 12.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Contorno de objeção', 'Avaliação do contorno de objeção, considerando se, diante das objeções apresentadas pelo aluno, o agente realizou no mínimo três tentativas de contorno ao longo do contato, de forma coerente e alinhada ao contexto da ligação, indo além do cumprimento de protocolo e buscando conduzir a negociação com estratégia.', 12.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Fechamento da negociação', 'Avaliação do fechamento da negociação, aplicável tanto para casos de acordo formalizado quanto para recusa, considerando se o atendente orientou de forma clara sobre as condições ou, quando necessário, sobre as consequências do não pagamento, garantindo transparência e um encerramento adequado do atendimento.', 12.00, 0, 5);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NCG', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações erradas', 'Avaliação de informações erradas, considerando se o atendente deixou de transmitir corretamente as informações conforme descrito nas ferramentas de suporte (roteiro de atendimento, etc.), sendo aplicável apenas quando houver erro por parte do operador na orientação prestada ao cliente.', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas', 'Avaliação de informações incompletas, considerando se o atendente deixou de informar ou realizar itens previstos no checklist/roteiro do acompanhamento, como, por exemplo, o cadastro CPC em casos de acordo realizado, sendo registrada quando essa ausência puder gerar prejuízo para as partes envolvidas.', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Acordo indevido', 'Avaliar, considerando se o atendente registrou a negociação sem a devida confirmação do devedor, sendo analisado neste item possíveis indícios de má-fé na condução e no registro do atendimento.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Tabulação (Registro do atendimento)', 'Considerar se o atendente registrou corretamente o motivo do contato e as informações do atendimento em sistema, sendo apontado quando houver ausência de registro ou preenchimento incorreto.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Quebra de Sigilo', 'Avaliar se houve compartilhamento indevido de informações a terceiros ou falha na confirmação dos dados do titular antes de prosseguir com o atendimento, em desacordo com as diretrizes da LGPD, comprometendo a segurança e confidencialidade das informações.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Mau atendimento', 'Considerando se o atendente adotou postura desrespeitosa, impaciente, grosseira ou ríspida, bem como a realização de comentários impróprios, irônicos ou uso de palavras inadequadas, comprometendo a qualidade e a experiência do cliente.', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Desconexão da chamada (Derrubar a ligação', 'Considerando se o atendente encerrou a ligação sem justificativa, desconectando o cliente de forma indevida. Não deve ser aplicado em casos de falha sistêmica ou quando houver utilização do script adequado para encerramento por falta de comunicação.', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão de atendimento', 'Considerando se o atendente iniciou o contato após tempo superior a 20 segundos da entrada da chamada, manteve a ligação sem justificativa após recado da operadora ou caixa postal, ou abandonou o atendimento sem motivo. Também se aplica quando permanece em linha diante de chamada muda, sem a devida tratativa, caracterizando falha na condução do atendimento.', NULL, 1, 8);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
INSERT INTO formularios (cliente_id, nome, descricao, categoria, tipo_calculo, status, versao)
INSERT INTO campanhas (cliente_id, nome, canal, ativa) VALUES (@cliente_id, @campanha_nome, 'telefone', 1) ON DUPLICATE KEY UPDATE canal=VALUES(canal), ativa=1;
INSERT IGNORE INTO formulario_campanhas (formulario_id, campanha_id) VALUES (@formulario_id, @campanha_id);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Abertura (peso 14)', 'Avalia se o operador inicia o atendimento de forma cordial e profissional, identifica-se corretamente, informa o motivo do contato, realiza a confirmação de dados quando aplicável e estabelece uma comunicação clara e acolhedora desde o início da ligação.', 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prontidão', 'O operador atendeu a ligação em até 3s?', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Abertura do contato', 'Ao iniciar a ligação chamar o cliente pelo nome e informar que é da Vero Informar que existe pagamento em atraso.', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Apresentação do débito', 'Informa com precisão valores vencidos, data de vencimento e referência do produto/serviço.', 4.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Sondagem', 'Sondagem com questionamentos pertinentes para identificar o motivo da inadimplência ou problema mencionado com o objetivo de personalizar a abordagem , oferecendo as melhores opções de negociação, como parcelamento ou renegociação com desconto.', 7.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Consulta de sistemas', 'Consultar os sistemas (CRMs) para identificar origem do débito, data do débito , empresa de origem entre outras informações que possam contribuir com a argumentação e fechamento da negociação com o cliente.', 3.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificação Positiva (Quebra de sigilo)', 'Questionar os dados do cliente e não informar o que está em sistema. Confirmar a titularidade do contrato (solicitar o nr do CPF). Em caso de terceiros confirmar os seguintes CPF do titular e nome completo e se está registrado como contato em sistema. Somente maiores de 18 anos. Obs: Qualquer alteração no contrato como: alteração de plano(downgrade ou upgrade), endereço, data de vencimento etc somente será feito com o titular.', 6.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Desenvolvimento (peso 43)', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Negociação gradativa', '1ª : Pagamento à vista sem desconto ate D+3 2ª: Pagamento à vista sem desconto até D+5 3ª : Desconto de acordo com aging da fatura 4ª: Parcelamento Obs: seguir a política de cobrança vigente.', 10.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Benefícios / Quebra de Objeções', 'Argumentar mostrando os beneficios em realizar a negociação, reabilitação do sinal, evitar a cobrança de juros e multa evitando a inclusão de débito em órgao de proteção ao crédito(Serasa),', 7.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Formas de pagamento', 'Apresenta alternativas disponíveis e confirma a mais conveniente para o cliente (Pix, boleto, cartão, débito automático). Obs: Pagamento no PIX, QR code ou Cartão de crédito se feito na área logada no APP a habilitação dos serviços é em até 3 horas.', 6.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Atualização Cadastral', 'Realizou atualização cadastral, confirmando e-mail e telefones cadastrados.(Questionar os dados do cliente e não informar o que está em sistema.) Obs: Qualquer alteração no cadastro somente será feito com o titular. Poderá incluir os dados do terceiro que está nos contatando , mas não poderá excluir os dados existentes.', 4.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Procedimentos e Políticas', 'Orientar o cliente de maneira correta, referente aos procedimentos. Realizar transferências se necessário e estiver dentro do procedimento.', 5.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Escuta ativa', 'Atentar-se às informações transmitidas pelos clientes; Escuta ativa; Foco durante o atendimento', 5.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Comunicação (peso 33)', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cordialidade', 'Manter um relacionamento íntegro com o cliente. Tratar o cliente com respeito, educação e profissionalismo, Empatia, Flexibilidade, velocidade de voz adequado ao entendimento do cliente.', 3.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Linguagem', 'A comunicação foi assertiva. Utilizou expressões adequadas, sem linguagem técnica, português correto e sem vício excessivo de linguagem.', 3.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Objetividade', 'Ter clareza nas informações transmitidas, direto e focado no propósito da chamada, que é a renegociação da dívida. Conduzir a ligação de forma eficiente e produtiva com a finalidade de regularização dos débitos.', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Pausas', 'Realizar acordo de espera esclarecendo ao cliente o motivo de estar em pausa. Retornar a cada 1 minuto . Evitar colocar no mute. Agradecer ao retornar da pausa . Personalizar o contato. Não falar com terceiros fora do mute.', 3.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Validação do acordo', 'Reforçou as condições da negociação: 1: Valor; 2: Data de vencimento; 3: Forma de pagamento (Se pagar pelo APP ou QR Code o serviço é habilitado em até 3 horas)', 4.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Consequências pelo atraso', 'Destacar a importância de cumprir o pagamento dentro dos prazos acordados ou em caso de insucesso refoçou a continuidade das ações de cobrança. 1: Ligações contínuas; 2: Juros e multas corrigidos diariamente; 3: Restrição do nome; 4. Perda das condições formalizadas (em caso de acordo quebrados) .', 4.00, 0, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro do atendimento', 'Registrou o atendimento no sistema de acordo com o que ficou formalizado em linha. Tabulação correta.', 4.00, 0, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'App', 'Orientar o acessos ao App Minha Vero informando que nele poderá efetuar o pagamento de suas faturas com Pix, cartão de crédito e débito automático entre outros serviços.', 4.00, 0, 8);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Encerramento', 'Saudação final em nome da Vero colocando-se à disposição do cliente.', 3.00, 0, 9);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NCG', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Perda e ou abandono da ligação', 'Desligar a ligação do cliente propositalmente ou abandonar o atendimento (demora no atendimento ou retornar, fazendo com que o cliente desligue).', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Segurar linha e ou ouvir mensagens eletrônicas', 'Segurar linha após finalizar o contato (após 1minuto). Permanecer ouvindo mensagens, sinais eletrônicos desnecessariamente.', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Agressividade/Coação/Ameaça', 'Ofender moralmente a imagem do cliente (mesmo que ele não tenha ouvido), utilizar palavras de baixo calão, deixar o cliente constrangido, provocar irritação no cliente por meio de ironias ou ameaças.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Repassar informações incorretas e/ou inexistentes.', 'Garantias indevidas: Repassar informações incorretas e/ou inexistentes. Prometer o que não é possível cumprir.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ética', 'Manter a imparcialidade quanto aos comentários do cliente e não comprometer a imagem da empresa, seus produtos ou serviços. Não orientar o cliente a acionar os órgãos de defesa do consumidor, como: ANATEL, PROCON, Juizado de Pequenas Causas, Ouvidoria, etc. Não registrar em sistema informações no histórico que comprometa a imagem do cliente. Não fazer ligação particular da PA.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informar valores incorretos', 'Não informar valores que não condizem com o débito do cliente. Caso cliente efetue o pagamento abaixo do mínimo sempre informar que valores restantes serão calculados automaticamente na próxima fatura.', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Promessa Indevida/ Quebra de Acordo', 'Registrar promessa em sistema sem a confirmação ou em data diferente da acordada com o cliente. Realizar acordo sem a certeza do pagamento. Registrar promessa de pagamento sem ter realizado contato com o cliente. Operador informa a data de vencimento do boleto e orienta o cliente a retornar na data para alterar o vencimento caso não consiga efetuar o pagamento. Incentivar o cliente a realizar nova negociação (quebrar acordo anterior) desnecessariamente.', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Atualização Cadastral', 'Não realizou atualização cadastral, confirmando e-mail e telefones cadastrados.(Questionar os dados do cliente e não informar o que está em sistema.) Obs: Qualquer alteração no cadastro somente será feito com o titular. Poderá incluir os dados do terceiro que está nos contatando , mas não poderá excluir os dados existentes.', NULL, 1, 8);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificação Positiva (Quebra de sigilo)', 'Questionar os dados do cliente e não informar o que está em sistema. Confirmar a titularidade do contrato (solicitar o nr do CPF). Em caso de terceiros confirmar os seguintes CPF do titular e nome completo e se está registrado como contato em sistema. Somente maiores de 18 anos.', NULL, 1, 9);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão de Atendimento', 'Iniciou o atendimento em tempo superior a 20 segundos após a entrada da chamada / Segurou a ligação sem justificativa após recado da operadora ou caixa postal. Abandonou a ligação enquanto prestava o atendimento sem motivo. (Ex.: Caso o agente permaneça em linha após identificar que a chamada está muda caracteriza-se como omissão de atendimento).', NULL, 1, 10);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
INSERT INTO formularios (cliente_id, nome, descricao, categoria, tipo_calculo, status, versao)
INSERT INTO campanhas (cliente_id, nome, canal, ativa) VALUES (@cliente_id, @campanha_nome, 'outro', 1) ON DUPLICATE KEY UPDATE canal=VALUES(canal), ativa=1;
