INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Atualização Cadastral', 'Não realizou atualização cadastral, confirmando e-mail e telefones cadastrados.(Questionar os dados do cliente e não informar o que está em sistema.) Obs: Qualquer alteração no cadastro somente será feito com o titular. Poderá incluir os dados do terceiro que está nos contatando , mas não poderá excluir os dados existentes.', NULL, 1, 8);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificação Positiva (Quebra de sigilo)', 'Questionar os dados do cliente e não informar o que está em sistema. Confirmar a titularidade do contrato (solicitar o nr do CPF). Em caso de terceiros confirmar os seguintes CPF do titular e nome completo e se está registrado como contato em sistema. Somente maiores de 18 anos.', NULL, 1, 9);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão de Atendimento', 'Iniciou o atendimento em tempo superior a 20 segundos após a entrada da chamada / Segurou a ligação sem justificativa após recado da operadora ou caixa postal. Abandonou a ligação enquanto prestava o atendimento sem motivo. (Ex.: Caso o agente permaneça em linha após identificar que a chamada está muda caracteriza-se como omissão de atendimento).', NULL, 1, 10);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
INSERT INTO formularios (cliente_id, nome, descricao, categoria, tipo_calculo, status, versao)
INSERT INTO campanhas (cliente_id, nome, canal, ativa) VALUES (@cliente_id, @campanha_nome, 'telefone', 1) ON DUPLICATE KEY UPDATE canal=VALUES(canal), ativa=1;
INSERT IGNORE INTO formulario_campanhas (formulario_id, campanha_id) VALUES (@formulario_id, @campanha_id);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'ABERTURA (peso 20)', NULL, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação, Apresentação e Identificação da Empresa', 'Descrição: Alô, xxx (cliente)? Me chamo (operador). Falo da assessoria financeira Grupo DDM, representante das lojas Avenida.', 9.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, '04 – Confirmação de dados', 'Descrição: Posso falar com (nome e sobrenome)? Observação: Não considerar se, na abertura, o operador chamou o cliente pelo nome e o mesmo confirmou.', 4.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Gravação', 'Informar que a ligação está sendo gravada.', 7.00, 0, 3);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Negociação (peso 17)', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Apresentação do débito', 'Apresentou o motivo do contato informando que é para falar sobre o débito referente ao cartão xxx. O débito encontra-se em atraso desde o dia (data), totalizando o saldo em aberto de R$ xxx, corrigido com multas e juros.', 17.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Sondagem', 'Sondou particularidades que possam contribuir para o aceite do acordo, utilização de perguntas de acordo com o diálogo.', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Negociação gradativa', '### 15 – Negociação Gradativa **Descrição:** Apresentar inicialmente a proposta para pagamento à vista. Em caso de recusa, compreender a condição do cliente e, gradativamente, apresentar alternativas de parcelamento que possibilitem a regularização do débito, buscando sempre uma condição que o cliente tenha possibilidade de cumprir e visando o fechamento do acordo.', 15.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Argumentação', 'Com base no discurso do "cliente", fez colocações pertinentes, argumentando em prol de conduzir o contato rumo ao aceite do mesmo? Neste ponto será avaliada a capacidade do agente em mostrar as características x benefícios de nosso negócio. Exemplo: O valor do acordo à vista está com desconto de 20%, de "R$ xx,xx" o valor vai para "R$ yy,yy".', 10.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Procedimento (peso 22)', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Benefícios da Negociação', '### 06 – Benefícios da Negociação **Descrição:** Apresentar ao cliente os principais benefícios da regularização do débito, destacando a possibilidade de retirada da restrição do CPF/CNPJ dos órgãos de proteção ao crédito, evitar ações judiciais, protestos e ligações recorrentes, além de possibilitar a recuperação do acesso a crédito, financiamentos e cartões.', 6.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Consequências do não pagamento', 'Consequências do Não Pagamento Orientar o cliente sobre as consequências da permanência do débito em aberto, destacando o acréscimo de juros e multas, a possibilidade de ligações recorrentes, a negativação junto aos órgãos de proteção ao crédito e a dificuldade para obtenção de crédito, financiamentos e cartões.', 6.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Confirmação do acordo', 'Reforçar o acordo realizado com o cliente, confirmando as condições negociadas, o valor da entrada ou pagamento à vista, a quantidade de parcelas, quando houver, e a data de vencimento, garantindo que o cliente tenha ciência e concorde com as condições estabelecidas.', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Atualização do telefone', 'Confirmar se o número utilizado no contato possui WhatsApp e, em caso positivo, realizar a atualização do cadastro, garantindo que o contato esteja atualizado para futuras comunicações.', 5.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Fechamento (peso 14)', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Se colocar a disposição', 'Ao finalizar o atendimento, colocar-se à disposição do cliente, verificando se ficou alguma dúvida em relação à negociação realizada e oferecendo suporte para eventuais esclarecimentos.', 3.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Orientar 0800', 'Em caso de dúvidas, orientar o cliente a entrar em contato pelo 0800 ou acessar o site fácil.quitar.com.br para obter mais informações e suporte.', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Encerramento', 'A DDM agradece a atenção e permanece à disposição para quaisquer dúvidas ou esclarecimentos. Desejar um bom dia/boa tarde ao cliente e finalizar o atendimento de forma cordial.', 3.00, 0, 3);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NCG - Não conformidade Grave', 'Caracteriza-se como uma falha crítica cometida durante o atendimento, capaz de comprometer a qualidade, a segurança, a negociação ou a experiência do cliente.', 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações erradas', 'Não passou as informações corretamente, conforme descrito nas ferramentas de suporte (Roteiro de atendimento, etc)?', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas', 'Informou todos os itens descritos no "check list / roteiro" contido no Acompanhamento?', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Acordo Indevido', 'Fechou a negociação sem a confirmação do devedor.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Tabulação (Registro do atendimento)', 'Não registrou corretamente o motivo do contato/Não registrou o atendimento.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Quebra de Sigilo', 'Passou informações para terceiros indevidamente /Confirmação dos dados para prosseguir o atendimento (LGPD).', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Mau Atendimento', 'Foi desrespeitoso, impaciente, grosseiro, ríspido, fez comentários impróprios, irônicos ou utilizou palavras chulas.', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Desconexão da chamada (Derrubar a ligação)', 'Desconectou o cliente durante a ligação sem justificativa. Não considerar este item, caso haja problemas de sistema ou o operador utilizar o "script" para encerramento de chamada (Ex.: Por falta de comunicação a ligação será encerrada).', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão de Atendimento', '- Iniciou o atendimento em tempo superior a 20 segundos após a entrada da chamada / Segurou a ligação sem justificativa após recado da operadora ou caixa postal. Abandonou a ligação enquanto prestava o atendimento sem motivo. (Ex.: Caso o agente permaneça em linha após identificar que a chamada está muda caracteriza-se como omissão de atendimento).', NULL, 1, 8);
