INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Análises de casos de quedas de ligações', NULL, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Avalie se foi corretamente identificado o motivo do encerramento da ligação, verificando se a chamada foi interrompida por falha sistêmica/técnica, encerrada indevidamente pelo operador ou finalizada ', 'Classifique como: CONFORME: Quando houver evidências de que a ligação foi interrompida por falha sistêmica, instabilidade técnica ou outro motivo alheio à ação do operador e à vontade do cliente e NÃO CONFORME: Quando houver evidências de que o operador encerrou o atendimento de forma indevida durante a interação com o cliente; ou o cliente encerrou a ligação por desinteresse, insatisfação ou desistência durante o atendimento. Considere o contexto da ligação, os indícios apresentados na chamada para determinar a causa do encerramento. Resultado esperado: Retornar apenas "CONFORME" ou "NÃO CONFORME", acompanhado de uma breve justificativa baseada nas evidências identificadas.', 0.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Avalie se o operador conduziu a abordagem de forma profissional, engajada e assertiva durante todo o atendimento. Considere tom de voz, interesse demonstrado, capacidade de criar conexão com o cliente', 'Classifique como: CONFORME: Quando o operador demonstra interesse genuíno no atendimento, mantém postura proativa, cordial e engajada, utiliza argumentação adequada e contribui para manter o interesse do cliente na negociação e NÃO CONFORME: Quando o operador apresenta postura passiva, desinteressada, apática ou mecânica, demonstra falta de empenho na condução da negociação, não explora adequadamente as necessidades do cliente ou contribui para a perda de interesse e encerramento da tratativa. Resultado esperado: Retornar apenas "CONFORME" ou "NÃO CONFORME", com uma breve justificativa baseada em evidências da interação.', 0.00, 0, 2);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
INSERT INTO formularios (cliente_id, nome, descricao, categoria, tipo_calculo, status, versao)
INSERT INTO campanhas (cliente_id, nome, canal, ativa) VALUES (@cliente_id, @campanha_nome, 'outro', 1) ON DUPLICATE KEY UPDATE canal=VALUES(canal), ativa=1;
INSERT IGNORE INTO formulario_campanhas (formulario_id, campanha_id) VALUES (@formulario_id, @campanha_id);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Abertura (peso 14)', 'Avalia se o operador inicia o atendimento de forma cordial e profissional, identifica-se corretamente, informa o motivo do contato, realiza a confirmação de dados quando aplicável e estabelece uma comunicação clara e acolhedora desde o início da ligação.', 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prontidão', 'O operador atendeu a ligação em até 3s?', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Abertura do contato', 'Ao iniciar a ligação chamar o cliente pelo nome e informar que é da Vero Informar que existe pagamento em atraso.', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Apresentação do débito', 'Informa com precisão valores vencidos, data de vencimento e referência do produto/serviço.', 4.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Sondagem', 'Sondagem com questionamentos pertinentes para identificar o motivo da inadimplência ou problema mencionado com o objetivo de personalizar a abordagem , oferecendo as melhores opções de negociação, como parcelamento ou renegociação com desconto.', 7.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Consulta de sistemas', 'Consultar os sistemas (CRMs) para identificar origem do débito, data do débito , empresa de origem entre outras informações que possam contribuir com a argumentação e fechamento da negociação com o cliente.', 3.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificação Positiva (Quebra de sigilo)', 'Questionar os dados do cliente e não informar o que está em sistema. Confirmar a titularidade do contrato (solicitar o nr do CPF). Em caso de terceiros confirmar os seguintes CPF do titular e nome completo e se está registrado como contato em sistema. Somente maiores de 18 anos. Obs: Qualquer alteração no contrato como: alteração de plano(downgrade ou upgrade), endereço, data de vencimento etc somente será feito com o titular.', 6.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Desenvolvimento (peso 43)', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Negociação gradativa', '1ª : Pagamento à vista sem desconto ate D+3 2ª: Pagamento à vista sem desconto até D+5 3ª : Desconto de acordo com aging da fatura 4ª: Parcelamento Obs: seguir a política de cobrança vigente.', 10.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Benefícios / Quebra de Objeções', 'Argumentar mostrando os beneficios em realizar a negociação, reabilitação do sinal, evitar a cobrança de juros e multa evitando a inclusão de débito em órgao de proteção ao crédito(Serasa),', 7.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Formas de pagamento', 'Apresenta alternativas disponíveis e confirma a mais conveniente para o cliente (Pix, boleto, cartão, débito automático). Obs: Pagamento no PIX, QR code ou Cartão de crédito se feito na área logada no APP a habilitação dos serviços é em até 3 horas.', 6.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Atualização Cadastral', 'Realizou atualização cadastral, confirmando e-mail e telefones cadastrados.(Questionar os dados do cliente e não informar o que está em sistema.) Obs: Qualquer alteração no cadastro somente será feito com o titular. Poderá incluir os dados do terceiro que está nos contatando , mas não poderá excluir os dados existentes.', 4.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Procedimentos e Políticas', 'Orientar o cliente de maneira correta, referente aos procedimentos. Realizar transferências se necessário e estiver dentro do procedimento.', 5.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Escuta ativa', 'Atentar-se às informações transmitidas pelos clientes; Escuta ativa; Foco durante o atendimento', 5.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Comunicação (peso 33)', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cordialidade', 'Manter um relacionamento íntegro com o cliente. Tratar o cliente com respeito, educação e profissionalismo, Empatia, Flexibilidade, velocidade de voz adequado ao entendimento do cliente.', 3.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Linguagem', 'A comunicação foi assertiva. Utilizou expressões adequadas, sem linguagem técnica, português correto e sem vício excessivo de linguagem.', 3.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Objetividade', 'Ter clareza nas informações transmitidas, direto e focado no propósito da chamada, que é a renegociação da dívida. Conduzir a ligação de forma eficiente e produtiva com a finalidade de regularização dos débitos.', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Pausas', 'Realizar acordo de espera esclarecendo ao cliente o motivo de estar em pausa. Retornar a cada 1 minuto . Evitar colocar no mute. Agradecer ao retornar da pausa . Personalizar o contato. Não falar com terceiros fora do mute.', 3.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Validação do acordo', 'Reforçou as condições da negociação: 1: Valor; 2: Data de vencimento; 3: Forma de pagamento (Se pagar pelo APP ou QR Code o serviço é habilitado em até 3 horas)', 4.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Consequências pelo atraso', 'Destacar a importância de cumprir o pagamento dentro dos prazos acordados ou em caso de insucesso refoçou a continuidade das ações de cobrança. 1: Ligações contínuas; 2: Juros e multas corrigidos diariamente; 3: Restrição do nome; 4. Perda das condições formalizadas (em caso de acordo quebrados) .', 4.00, 0, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro do atendimento', 'Registrou o atendimento no sistema de acordo com o que ficou formalizado em linha. Tabulação correta.', 4.00, 0, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'App', 'Orientar o acessos ao App Minha Vero informando que nele poderá efetuar o pagamento de suas faturas com Pix, cartão de crédito e débito automático entre outros serviços.', 4.00, 0, 8);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Encerramento', 'Saudação final em nome da Vero colocando-se à disposição do cliente.', 3.00, 0, 9);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NCG', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Perda e ou abandono da ligação', 'Desligar a ligação do cliente propositalmente ou abandonar o atendimento (demora no atendimento ou retornar, fazendo com que o cliente desligue).', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Segurar linha e ou ouvir mensagens eletrônicas', 'Segurar linha após finalizar o contato (após 1minuto). Permanecer ouvindo mensagens, sinais eletrônicos desnecessariamente.', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Agressividade/Coação/Ameaça', 'Ofender moralmente a imagem do cliente (mesmo que ele não tenha ouvido), utilizar palavras de baixo calão, deixar o cliente constrangido, provocar irritação no cliente por meio de ironias ou ameaças.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Repassar informações incorretas e/ou inexistentes.', 'Garantias indevidas: Repassar informações incorretas e/ou inexistentes. Prometer o que não é possível cumprir.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ética', 'Manter a imparcialidade quanto aos comentários do cliente e não comprometer a imagem da empresa, seus produtos ou serviços. Não orientar o cliente a acionar os órgãos de defesa do consumidor, como: ANATEL, PROCON, Juizado de Pequenas Causas, Ouvidoria, etc. Não registrar em sistema informações no histórico que comprometa a imagem do cliente. Não fazer ligação particular da PA.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informar valores incorretos', 'Não informar valores que não condizem com o débito do cliente. Caso cliente efetue o pagamento abaixo do mínimo sempre informar que valores restantes serão calculados automaticamente na próxima fatura.', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Promessa Indevida/ Quebra de Acordo', 'Registrar promessa em sistema sem a confirmação ou em data diferente da acordada com o cliente. Realizar acordo sem a certeza do pagamento. Registrar promessa de pagamento sem ter realizado contato com o cliente. Operador informa a data de vencimento do boleto e orienta o cliente a retornar na data para alterar o vencimento caso não consiga efetuar o pagamento. Incentivar o cliente a realizar nova negociação (quebrar acordo anterior) desnecessariamente.', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Atualização Cadastral', 'Não realizou atualização cadastral, confirmando e-mail e telefones cadastrados.(Questionar os dados do cliente e não informar o que está em sistema.) Obs: Qualquer alteração no cadastro somente será feito com o titular. Poderá incluir os dados do terceiro que está nos contatando , mas não poderá excluir os dados existentes.', NULL, 1, 8);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
INSERT INTO formularios (cliente_id, nome, descricao, categoria, tipo_calculo, status, versao)
INSERT INTO campanhas (cliente_id, nome, canal, ativa) VALUES (@cliente_id, @campanha_nome, 'outro', 1) ON DUPLICATE KEY UPDATE canal=VALUES(canal), ativa=1;
INSERT IGNORE INTO formulario_campanhas (formulario_id, campanha_id) VALUES (@formulario_id, @campanha_id);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Abertura (peso 14)', 'Avalia se o operador inicia o atendimento de forma cordial e profissional, identifica-se corretamente, informa o motivo do contato, realiza a confirmação de dados quando aplicável e estabelece uma comunicação clara e acolhedora desde o início da ligação.', 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prontidão', 'O operador atendeu a ligação em até 3s?', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Abertura do contato', 'Ao iniciar a ligação chamar o cliente pelo nome e informar que é da Vero Informar que existe pagamento em atraso.', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Apresentação do débito', 'Informa com precisão valores vencidos, data de vencimento e referência do produto/serviço.', 4.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Sondagem', 'Sondagem com questionamentos pertinentes para identificar o motivo da inadimplência ou problema mencionado com o objetivo de personalizar a abordagem , oferecendo as melhores opções de negociação, como parcelamento ou renegociação com desconto.', 7.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Consulta de sistemas', 'Consultar os sistemas (CRMs) para identificar origem do débito, data do débito , empresa de origem entre outras informações que possam contribuir com a argumentação e fechamento da negociação com o cliente.', 3.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificação Positiva (Quebra de sigilo)', 'Questionar os dados do cliente e não informar o que está em sistema. Confirmar a titularidade do contrato (solicitar o nr do CPF). Em caso de terceiros confirmar os seguintes CPF do titular e nome completo e se está registrado como contato em sistema. Somente maiores de 18 anos. Obs: Qualquer alteração no contrato como: alteração de plano(downgrade ou upgrade), endereço, data de vencimento etc somente será feito com o titular.', 6.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Desenvolvimento (peso 43)', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Negociação gradativa', '1ª : Pagamento à vista sem desconto ate D+3 2ª: Pagamento à vista sem desconto até D+5 3ª : Desconto de acordo com aging da fatura 4ª: Parcelamento Obs: seguir a política de cobrança vigente.', 10.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Benefícios / Quebra de Objeções', 'Argumentar mostrando os beneficios em realizar a negociação, reabilitação do sinal, evitar a cobrança de juros e multa evitando a inclusão de débito em órgao de proteção ao crédito(Serasa),', 7.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Formas de pagamento', 'Apresenta alternativas disponíveis e confirma a mais conveniente para o cliente (Pix, boleto, cartão, débito automático). Obs: Pagamento no PIX, QR code ou Cartão de crédito se feito na área logada no APP a habilitação dos serviços é em até 3 horas.', 6.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Atualização Cadastral', 'Realizou atualização cadastral, confirmando e-mail e telefones cadastrados.(Questionar os dados do cliente e não informar o que está em sistema.) Obs: Qualquer alteração no cadastro somente será feito com o titular. Poderá incluir os dados do terceiro que está nos contatando , mas não poderá excluir os dados existentes.', 4.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Procedimentos e Políticas', 'Orientar o cliente de maneira correta, referente aos procedimentos. Realizar transferências se necessário e estiver dentro do procedimento.', 5.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Escuta ativa', 'Atentar-se às informações transmitidas pelos clientes; Escuta ativa; Foco durante o atendimento', 5.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Comunicação (peso 33)', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cordialidade', 'Manter um relacionamento íntegro com o cliente. Tratar o cliente com respeito, educação e profissionalismo, Empatia, Flexibilidade, velocidade de voz adequado ao entendimento do cliente.', 3.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Linguagem', 'A comunicação foi assertiva. Utilizou expressões adequadas, sem linguagem técnica, português correto e sem vício excessivo de linguagem.', 3.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Objetividade', 'Ter clareza nas informações transmitidas, direto e focado no propósito da chamada, que é a renegociação da dívida. Conduzir a ligação de forma eficiente e produtiva com a finalidade de regularização dos débitos.', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Pausas', 'Realizar acordo de espera esclarecendo ao cliente o motivo de estar em pausa. Retornar a cada 1 minuto . Evitar colocar no mute. Agradecer ao retornar da pausa . Personalizar o contato. Não falar com terceiros fora do mute.', 3.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Validação do acordo', 'Reforçou as condições da negociação: 1: Valor; 2: Data de vencimento; 3: Forma de pagamento (Se pagar pelo APP ou QR Code o serviço é habilitado em até 3 horas)', 4.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Consequências pelo atraso', 'Destacar a importância de cumprir o pagamento dentro dos prazos acordados ou em caso de insucesso refoçou a continuidade das ações de cobrança. 1: Ligações contínuas; 2: Juros e multas corrigidos diariamente; 3: Restrição do nome; 4. Perda das condições formalizadas (em caso de acordo quebrados) .', 4.00, 0, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro do atendimento', 'Registrou o atendimento no sistema de acordo com o que ficou formalizado em linha. Tabulação correta.', 4.00, 0, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'App', 'Orientar o acessos ao App Minha Vero informando que nele poderá efetuar o pagamento de suas faturas com Pix, cartão de crédito e débito automático entre outros serviços.', 4.00, 0, 8);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Encerramento', 'Saudação final em nome da Vero colocando-se à disposição do cliente.', 3.00, 0, 9);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NCG', NULL, 4);
