INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Abertura do Atendimento', NULL, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação inicial', 'Realizou abertura adequada, com saudação e identificação.', 5.00, 0, 1);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Identificação e Entendimento da Demanda', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Clareza na comunicação', 'A comunicação do Operador (a) foi clara, objetiva e de fácil entendimento / Informou o motivo do contato. Ex.: “Estamos entrando em contato para informar que sua empresa está apta a participar do Projeto Brasil Mais Produtivo”', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Entendimento da necessidade', 'Conduziu a ligação com clareza e precisão / Buscou compreender corretamente a demanda(informativo ou prospecção) antes de iniciar o contato', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Direcionamento correto', 'Conduziu o atendimento de forma assertiva, sem gerar dúvidas ou retrabalho / Houve menção indevida ao Governo durante o atendimento, independentemente da situação / Esclareceu que a consultoria depende de planejamento com o SENAI-RS e direciona corretamente para o agendamento com a equipe responsável pela continuidade do atendimento.', 10.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'CAMPANHA INFORMATIVA - Passou as informações completas', 'Transmitiu todas as informações necessárias com segurança (de acordo com roteiro)', 10.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'CAMPANHA DE PROSPECÇÃO - Desenvolvimento da negociação', 'Explorou a necessidade e criou oportunidade de negociação, conforme roteiro.', 10.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'CAMPANHA INFORMATIVA - Conferência de entendimento', 'Confirmou se o cliente compreendeu as orientações.', 10.00, 0, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'CAMPANHA DE PROSPECÇÃO - Argumentação e contorno de objeção', 'Utilizou argumentos adequados para tentar reverter objeções.', 10.00, 0, 7);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Empatia e Relacionamento com o Cliente', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Linguagem inadequada', 'Gírias e vícios de Linguagem (tá, ok, né, hum-hum, no caso ou outras expressões repetidas) / Verbos no condicional (gostaria, seria, poderia) em demasiado, uso do diminutivo. (UTILIZANDO A REGRA DE TRÊS REPETIÇÕES) É preciso utilizar linguagem simples e Gírias e vícios de Linguagem (tá, ok, né, hum-hum, no caso ou outras expressões repetidas) / Verbos no condicional (gostaria, seria, poderia), uso do diminutivo / Evitou termos técnicos que são de conhecimento interno (regimental, PFO, nomenclatura, módulos, comunidade) / Palavras ou expressões negativas (infelizmente, problema, dúvida, demora, etc.) / Gerundismo (vamos estar enviando, vou estar fazendo, vou estar registrando) / Pronúncia e concordância', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Erros de digitação no registro', 'Cometeu erros de digitação no registro (concordância, pontuação e etc)', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cordialidade', 'Demonstrou educação, empatia e utilizou palavras de cortesia (por gentileza/obrigado(a) e etc.)', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Entonação', 'Utilizou adequadamente os tons de voz, modulando-o conforme necessidade / Tom de voz agradável amigável e sorriso na voz / Estabeleceu o mesmo ritmo de conversa do cliente.', 5.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ausência prolongada', 'Não justificou a ausência e/ou ficou ausente por longos períodos (Acima de 1 minuto)', 5.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Personalizou o atendimento', 'Chamou o cliente pelo nome no mínimo 3 vezes durante o atendimento', 5.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Encerramento do Atendimento', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação final', 'Utilizou fraseologia de finalização adequada', 5.00, 0, 1);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Erros Críticos (NCG)', NULL, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Entonação / Falta de cordialidade', 'Utilizou palavras de baixo calão, tom de voz irônico, ríspido, demonstrou ausência de atenção total e/ou impaciência / Utilizou frases “como já havia dito anteriormente”, "então" e etc', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão do atendimento (Indisponibilidade)', 'Não atendeu a necessidade do cliente / Encerrou a ligação sem finalizar o atendimento / Ficou mudo / Não prestou o atendimento, quando tinha acesso as informações e etc. / Não desenvolveu a informação/prospecção.', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ausência de tentativa de contorno de objeção', 'Não contornou as objeções do cliente de forma adequada.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Erro de processo que impacte diretamente o cliente / Informações incompletas e incorretas', 'Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitir informações relevantes que podem prejudicar o cliente ou gerar uma re-chamada / Transmitiu informação equivocada ou que não conste em nossos documentos / Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitiu informações incorretas que podem prejudicar o cliente ou gerar uma re-chamada.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Confirmação dos dados', 'Confirmou as informações fornecidas pelo cliente no intuito de garantir que estamos inserindo no sistema os dados corretos / Verificação da grafia, principalmente ao anotar endereços de e-mail, solicitando ao cliente que soletre, caso necessário.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Não encerrar o atendimento (prender a ligação)', 'Deixou a ligação "presa", não encerrou a ligação ao final do atendimento e/ou quando cai em Caixa Postal.', NULL, 1, 6);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
INSERT INTO formularios (cliente_id, nome, descricao, categoria, tipo_calculo, status, versao)
INSERT INTO campanhas (cliente_id, nome, canal, ativa) VALUES (@cliente_id, @campanha_nome, 'telefone', 1) ON DUPLICATE KEY UPDATE canal=VALUES(canal), ativa=1;
INSERT IGNORE INTO formulario_campanhas (formulario_id, campanha_id) VALUES (@formulario_id, @campanha_id);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, '1. Abertura', NULL, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prontidão', 'Operador iniciou o atendimento de imediato, até 5s.', 6.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação inicial', 'Sempre iniciar se apresentando, citando isaac, parceria com a escola, nome do responsável financeiro. Realize a confirmação positiva (LGPD) antes de prosseguir com o atendimento. Informe que a ligação é gravada. E', 8.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação Final', 'Encerrou o atendimento de forma cordial.', 6.00, 0, 3);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Desenvolvimento', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Comunicação de Ausência / Tempo de Espera', 'Comunicou que iria se ausentar, informando ao cliente que poderia chamá-lo a qualquer momento? Neste contexto não abandonou o contato por demasia deixando um vácuo na ligação.', 10.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Realização / Atualização do Cadastro', 'Perguntou se o e-mail e/ou telefone foram alterados para envio do boleto? Caso cadastro não tenha e-mail preenchido, solicitou este dado para envio do boleto?. Registrou corretamente os dados informados pelo cliente (nome, e-mail, telefone, etc.)?', 10.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Autoatendimento', 'Disponibilizou o aplicativo Meu Arco.', 10.00, 0, 3);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NEGOCIAÇÃO / COBRANÇA', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Proposta Inicial', 'Passou os valores da proposta, débitos incluídos na negociação e a data de pagamento disponível na plataforma, ressaltando como uma oportunidade única (gatilhos mentais).', 15.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Sondagem', 'Sondou particularidades que possam contribuir para o aceite do "aluno"? Utilização de perguntas de acordo com o diálogo.', 15.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Argumentação', 'Realizou colocações coerentes com a necessidade apresentada pelo cliente; Utilizar argumentação direcionada ao aceite da proposta; Demonstrar claramente as características e benefícios da negociação; Evidenciar vantagens financeiras, acadêmicas ou administrativas;', 10.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Fechamento da negociação', 'Avaliar se o operador reforçou corretamente as condições do acordo e orientou o cliente sobre as consequências da inadimplência. Reforçar a importância do pagamento dentro da data de vencimento; Informar, de forma clara, as consequências do não pagamento do acordo; Orientar sobre possíveis impactos, como: cancelamento do acordo; incidência de juros e multa; possibilidade de negativação do CPF junto aos órgãos de proteção ao crédito; Impossibilidade de rematrícula Demonstrar os impactos financeiros e administrativos da inadimplência.', 10.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NCG - Não Conformidade Grave', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações erradas', 'Não passou as informações corretamente conforme roteiro de atendimento ou ferramentas de suporte. Ex. Informou telefone errado time isaac; Direcionou app errado;', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Acordo indevido', 'Fechamento de negociação sem confirmação do devedor; Avalia possível má-fé ou falha grave no registro do atendimento;', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Tabulação (registro do atendimento)', 'Não registrou corretamente o motivo do contato. Não realizou o registro do atendimento no sistema.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Quebra de sigilo', 'Repasse indevido de informações a terceiros sem autorização. Falha na confirmação de dados conforme LGPD.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, '.Desconexão da chamada (derrubar ligação)', 'Desconexão da chamada sem justificativa. Não se aplica em caso de falha de sistema ou encerramento via script padrão.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão de atendimento', 'Demora superior a 20 segundos no início do atendimento; Abandono da ligação durante o atendimento sem justificativa; Segurar o cliente em linha sem ação(caixa postal, ligação muda)', NULL, 1, 6);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
