INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Vicios de linguagem', 'Avaliar o uso excessivo ou inadequado de palavras e expressões durante o atendimento que possam comprometer a clareza, objetividade e profissionalismo da comunicação. Exemplos: repetição de palavras, “né”, “tipo”, “então”, “tá”, “entendeu?”, “assim”, “certo?”, além de gírias, informalidades ou expressões inadequadas ao contexto.', 10.00, 0, 4);
