INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Vícios de linguagem', 'Uso do diminutivo; ''''ok'''' ''''ta bom'''' ''''ai''''', 5.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NEGOCIAÇÃO / COBRANÇA', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Proposta Inicial', 'Passou os valores da proposta, débitos incluídos na negociação e a data de pagamento disponível na plataforma, ressaltando como uma oportunidade única (gatilhos mentais).', 15.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Sondagem', 'Sondou particularidades que possam contribuir para o aceite do "aluno"? Utilização de perguntas de acordo com o diálogo.', 15.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Argumentação', 'Realizou colocações coerentes com a necessidade apresentada pelo cliente; Utilizar argumentação direcionada ao aceite da proposta; Demonstrar claramente as características e benefícios da negociação; Evidenciar vantagens financeiras, acadêmicas ou administrativas;', 10.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Fechamento da negociação', 'Avaliar se o operador reforçou corretamente as condições do acordo e orientou o cliente sobre as consequências da inadimplência. Reforçar a importância do pagamento dentro da data de vencimento; Informar, de forma clara, as consequências do não pagamento do acordo; Orientar sobre possíveis impactos, como: cancelamento do acordo; incidência de juros e multa; possibilidade de negativação do CPF junto aos órgãos de proteção ao crédito; Impossibilidade de rematrícula Demonstrar os impactos financeiros e administrativos da inadimplência.', 10.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NCG - Não Conformidade Grave', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações erradas', 'Não passou as informações corretamente conforme roteiro de atendimento ou ferramentas de suporte. Ex. Informou telefone errado time isaac; Direcionou app errado;', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Acordo indevido', 'Fechamento de negociação sem confirmação do devedor; Avalia possível má-fé ou falha grave no registro do atendimento;', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Tabulação (registro do atendimento)', 'Não registrou corretamente o motivo do contato. Não realizou o registro do atendimento no sistema.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Quebra de sigilo', 'Repasse indevido de informações a terceiros sem autorização. Falha na confirmação de dados conforme LGPD.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, '.Desconexão da chamada (derrubar ligação)', 'Desconexão da chamada sem justificativa. Não se aplica em caso de falha de sistema ou encerramento via script padrão.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão de atendimento', 'Demora superior a 20 segundos no início do atendimento; Abandono da ligação durante o atendimento sem justificativa; Segurar o cliente em linha sem ação(caixa postal, ligação muda)', NULL, 1, 6);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
