INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, '1. Abertura', NULL, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prontidão', 'Operador iniciou o atendimento em até 5 segundos.', 6.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação inicial', 'Sempre iniciar se apresentando, citando o nome da faculdade. Realize a confirmação positiva (LGPD) antes de prosseguir com o atendimento. Informe que a ligação é gravada. Ex: Alô, falo com o Leandro? Sim, Leandro. Meu nome é Gabriela, faço parte do grupo DDM , em parceria com a Uniriter, tudo bem?', 8.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação Final', 'Encerrou o atendimento de forma cordial.', 6.00, 0, 3);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Desenvolvimento', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Comunicação de Ausência / Tempo de Espera', 'Comunicou que iria se ausentar, informando ao cliente que poderia chamá-lo a qualquer momento? Neste contexto não abandonou o contato por demasia deixando um vácuo na ligação.', 10.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Realização / Atualização do Cadastro', 'Perguntou se o e-mail e/ou telefone foram alterados para envio do boleto? Caso cadastro não tenha e-mail preenchido, solicitou este dado para envio do boleto?. Registrou corretamente os dados informados pelo cliente (nome, e-mail, telefone, etc.)?', 5.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Autoatendimento', 'Disponibilizou o portal do aluno.', 2.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Personalizar', 'Chamar o aluno pelo nome ao menos 2x.', 5.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Vícios de linguagem', 'Avalia se o operador mantém uma comunicação clara e profissional, evitando o uso excessivo de gírias, diminutivo, expressões informais, palavras repetitivas e vícios de linguagem que comprometam a fluidez e a qualidade do atendimento. "Ok?" (utilizado repetidamente) "Então..." (em excesso) "Tá bom?" (repetidamente) Repetição excessiva de palavras, como: "certo", "perfeito", "então", "assim", "no caso", "tipo".', 8.00, 0, 5);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NEGOCIAÇÃO / COBRANÇA', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Proposta Inicial', 'Passou os valores da proposta, débitos incluídos na negociação e a data de pagamento disponível na plataforma, ressaltando como uma oportunidade única (gatilhos mentais).', 15.00, 0, 1);
