INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'CAMPANHA INFORMATIVA - Passou as informações completas', 'Transmitiu todas as informações necessárias com segurança (de acordo com roteiro)', 10.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'CAMPANHA DE PROSPECÇÃO - Desenvolvimento da negociação', 'Explorou a necessidade e criou oportunidade de negociação, conforme roteiro.', 10.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'CAMPANHA INFORMATIVA - Conferência de entendimento', 'Confirmou se o cliente compreendeu as orientações.', 10.00, 0, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'CAMPANHA DE PROSPECÇÃO - Argumentação e contorno de objeção', 'Utilizou argumentos adequados para tentar reverter objeções.', 10.00, 0, 7);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Empatia e Relacionamento com o Cliente', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cordialidade', 'Demonstrou educação, empatia e utilizou palavras de cortesia (por gentileza/obrigado(a) e etc.)', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Linguagem inadequada', 'Gírias e vícios de Linguagem (tá, ok, né, hum-hum, no caso ou outras expressões repetidas) / Verbos no condicional (gostaria, seria, poderia) em demasiado, uso do diminutivo. (UTILIZANDO A REGRA DE TRÊS REPETIÇÕES) É preciso utilizar linguagem simples e Gírias e vícios de Linguagem (tá, ok, né, hum-hum, no caso ou outras expressões repetidas) / Verbos no condicional (gostaria, seria, poderia), uso do diminutivo / Evitou termos técnicos que são de conhecimento interno (regimental, PFO, nomenclatura, módulos, comunidade) / Palavras ou expressões negativas (infelizmente, problema, dúvida, demora, etc.) / Gerundismo (vamos estar enviando, vou estar fazendo, vou estar registrando) / Pronúncia e concordância', 10.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Entonação', 'Utilizou adequadamente os tons de voz, modulando-o conforme necessidade / Tom de voz agradável amigável e sorriso na voz / Estabeleceu o mesmo ritmo de conversa do cliente.', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ausência prolongada', 'Não justificou a ausência e/ou ficou ausente por longos períodos (Acima de 1 minuto)', 5.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Personalizou o atendimento', 'Chamou o cliente pelo nome no mínimo 3 vezes durante o atendimento', 5.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Erros de digitação no registro', 'Cometeu erros de digitação no registro (concordância, pontuação e etc)', 5.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Encerramento do Atendimento', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação final', 'Utilizou fraseologia de finalização adequada', 5.00, 0, 1);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Erros Críticos (NCG)', NULL, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Entonação / Falta de cordialidade', 'Utilizou palavras de baixo calão, tom de voz irônico, ríspido, demonstrou ausência de atenção total e/ou impaciência / Utilizou frases “como já havia dito anteriormente”, "então" e etc', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas/Incorretas', 'Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitir informações relevantes que podem prejudicar o cliente ou gerar uma re-chamada / Transmitiu informação equivocada ou que não conste em nossos documentos.', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão do atendimento (Indisponibilidade)', 'Não atendeu a necessidade do cliente / Encerrou a ligação sem finalizar o atendimento / Ficou mudo / Não prestou o atendimento, quando tinha acesso as informações e etc. / Não desenvolveu a informação/prospecção.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ausência de tentativa de contorno de objeção', 'Não contornou as objeções do cliente de forma adequada.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Erro de processo que impacte diretamente o cliente / Informações incompletas e incorretas', 'Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitir informações relevantes que podem prejudicar o cliente ou gerar uma re-chamada / Transmitiu informação equivocada ou que não conste em nossos documentos / Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitiu informações incorretas que podem prejudicar o cliente ou gerar uma re-chamada.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Confirmação dos dados', 'Confirmou as informações fornecidas pelo cliente no intuito de garantir que estamos inserindo no sistema os dados corretos / Verificação da grafia, principalmente ao anotar endereços de e-mail, solicitando ao cliente que soletre, caso necessário.', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Não encerrar o atendimento (prender a ligação)', 'Deixou a ligação "presa", não encerrou a ligação ao final do atendimento e/ou quando cai em Caixa Postal.', NULL, 1, 7);
INSERT INTO clientes (slug, nome, ativo) VALUES (@cliente_slug, @cliente_nome, 1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), ativo=1;
