INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Abertura do Atendimento', NULL, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Pronto atendimento', 'Iniciou o atendimento prontamente (até 15 segundos) a partir da primeira interação do cliente.', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Confirmação de dados e atualização cadastral', 'Não confirmou e/ou solicitou os dados pessoais do cliente para registrar (CPF, endereço/e-mail/telefone) / Não registrou os dados em sistema de forma correta e completa.', 10.00, 0, 2);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Empatia e Relacionamento com o Cliente', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ausência e retorno justificados', 'Solicitou e justificou o momento solicitado / Agradeceu ao retornar / Ultrapassou mais de 5 minutos sem intreação com o cliente.', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Linguagem inadequada', 'Gírias e vícios de Linguagem (tá, ok, né, hum-hum, no caso ou outras expressões repetidas) / Verbos no condicional (gostaria, seria, poderia), uso do diminutivo / Evitou termos técnicos que são de conhecimento interno (regimental, PFO, nomenclatura, módulos, comunidade) / Palavras ou expressões negativas (infelizmente, problema, dúvida, demora, etc.) / Gerundismo (vamos estar enviando, vou estar fazendo, vou estar registrando) / Pronúncia e concordância. / Ausência ou acréscimo de palavras ou letras que não alterem o sentido da frase ou da palavra.', 10.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Demonstrou cordialidade durante o atendimento', 'Utilizou expressões de cordialidade durante a comunicação (obrigado(a), por gentileza, por favor e etc), demonstrou empatia e gentileza.', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Personalizou o atendimento', 'Chamou o cliente pelo nome no mínimo 3 vezes durante o atendimento', 5.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Erros de digitação no registro', 'Cometeu erros de digitação no registro (concordância, pontuação e etc)', 5.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro incompleto e/ou incorreto / Tabulação incompleta e/ou incorreta', 'Registrou ou tabulou o atendimento de forma incompleta e/ou incorreta.', 10.00, 0, 6);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Identificação e Entendimento da Demanda', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Condução do atendimento', 'Conduziu, organizou e explicou corretamente as informações, garantindo clareza, coerência, objetividade e alinhamento. / Editou a resposta pronta, excluindo informação ou acrescentando conforme a necessidade do cliente', 10.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificação de oportunidades', 'Oferecimento do curso solicitado em outras localidades caso não esteja disponível na unidade que o cliente sinalizou interesse / Oferecimento de outros cursos na mesma área solicitada pelo cliente / Informou sobre os serviços e campanhas disponíveis no momento', 10.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Perguntar se tem vínculo com a indústria', 'Questionou se o cliente possuí vínculo com a Indústria, para informar sobre valores diferenciados.', 5.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Realizou sondagem adequada.', 'Não realizou sondagem adequada e necessária para investigar o que o cliente deseja, e não entendeu sua real necessidade.', 10.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Encerramento do Atendimento', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Questionou se o cliente ficou com alguma dúvida ao final do atendimento.', 'Questionou se o cliente ficou com alguma dúvida ao final do atendimento (Algo mais em que posso ajudar?), (Ficou alguma dúvida?)', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Utilizou saudação final', 'Utilizou fraseologia de finalização: A Firjan agradece, tenha um excelente e/ou ótimo dia/tarde/noite.', 5.00, 0, 2);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Erros Críticos (NCG)', NULL, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ortografia e concordância verbal', 'Escreveu nomes próprios com letra maiúscula e/ou minúscula / Não teve atenção à forma correta da escrita das palavras / Concordância: verbal e etc', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Objetividade e resolutiva no primeiro contato', 'Não realizou a sondagem correta (caso gere algum prejuízo para o cliente), adequada e utiliza a resposta mais adequada à pergunta / Caso não seja possível utilizou um texto simples e claro, de acordo com a solicitação do cliente, evitando assim que entre contato conosco novamente.', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cordialidade durante o diálogo', 'Utilizou a frase “como já havia dito anteriormente/acima”, "então" / Foi ríspido (aumentou o tamanho da letra ao repetir uma informação por exemplo) / Não utilizou o negrito somente para informações benéficas (desconto, destaque do link que o cliente deve acessar e etc) / Utilizou palavras de baixo calão, tom irônico, ríspido, demonstrou ausência de atenção total e/ou impaciência.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas/Incorretas', 'Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitir informações relevantes que podem prejudicar o cliente ou gerar uma novo contato / Transmitiu informação equivocada ou que não conste em nossos documentos', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Pesquisa de satisfação', 'Não acrescentou o texto e o link da pesquisa de satisfação ao final da interação com o cliente, convidando o cliente a responder', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Classificação do ticket de atendimento', 'Não classificou o ticket do atendimento de forma completa e correta.', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro do atendimento', 'Não registrou o atendimento (Criou caso)', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão do atendimento (Indisponibilidade)', 'Não atendeu a necessidade do cliente / Encerrou a interação sem finalizar o atendimento / Não atendeu ao cliente / Não prestou o atendimento, quando tinha acesso as informações e etc', NULL, 1, 8);
