INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Abertura do atendimento', NULL, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prontidão no atendimento', 'Iniciou a tratativa do e-mail em até 24 horas úteis', 5.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação inicial', 'Iniciou o atendimento com: "A Firjan agradece seu contato." seguido do texto da LGPD + link', 5.00, 0, 2);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Empatia e Relacionamento com o Cliente', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Escrita inadequada', 'Gírias e vícios de Linguagem (tá, ok, né, hum-hum, no caso ou outras expressões repetidas) / Verbos no condicional (gostaria, seria, poderia), uso do diminutivo / Evitou termos técnicos que são de conhecimento interno (regimental, PFO, nomenclatura, módulos, comunidade) / Palavras ou expressões negativas (infelizmente, problema, dúvida, demora, etc.) / Gerundismo (vamos estar enviando, vou estar fazendo, vou estar registrando) / Pronúncia e concordância. / Ausência ou acréscimo de palavras ou letras que não alterem o sentido da frase ou da palavra.', 15.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro incompleto e/ou incorreto / Tabulação incompleta e/ou incorreta', 'Registrou ou tabulou o atendimento de forma incompleta e/ou incorreta.', 10.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Personalização', 'Inicia a resposta do e-mail utilizando Sr. ou Sra. + o nome do Cliente. Para os casos em que não consigamos identificar o gênero do cliente devermos utilizar Sr.(a) / Chama o cliente pelo nome de forma natural, durante o e-mail.', 10.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Erros de digitação', 'Cometeu erros de digitação no registro (concordância, pontuação e etc)', 10.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificou a necessidade do cliente', 'Não realizou sondagem adequada e necessária para investigar o que o cliente deseja, e não entendeu sua real necessidade (caso gere algum prejuízo para o cliente)', 10.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Identificação de oportunidades', 'Oferecimento do curso solicitado em outras localidades caso não esteja disponível na unidade que o cliente sinalizou interesse / Oferecimento de outros cursos na mesma área solicitada pelo cliente.', 10.00, 0, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Condução do atendimento', 'Conduziu, organizou e explicou corretamente as informações, garantindo clareza, coerência, objetividade e alinhamento / Editou respostas prontas.', 20.00, 0, 7);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Encerramento do atendimento', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Se colocou à disposição em caso de dúvidas', 'Questionou se o cliente ficou com alguma dúvida ao final do atendimento (Algo mais em que posso ajudar?), (Ficou alguma dúvida?)', 5.00, 0, 1);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Erros Críticos (NCG)', NULL, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'E-mails descartados', 'Não descartou de forma correta os e-mails que se encontram na caixa do Fale Conosco identificados como “spam” (e-mails de propaganda e etc)', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas/Incorretas', 'Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitir informações relevantes que podem prejudicar o cliente, deixando de citar questões importantes / Transmitiu informação equivocada ou que não conste em nossos documentos', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Credibilidade das Informações', 'Demonstrou conhecimento dos serviços e produtos da empresa / Realizou a busca correta das informações nos sistemas / Utilizou os manuais de apoio e da intranet para assegurar agilidade, precisão e qualidade durante o atendimento ao cliente.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Pesquisa de satisfação', 'Não acrescentou o texto e o link da pesquisa de satisfação em todas as respostas de e-mail.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cordialidade durante o diálogo', 'Utilizou a frase “como já havia dito anteriormente/acima”, "então" / Foi ríspido (aumentou o tamanho da letra ao repetir uma informação por exemplo) / Não utilizou o negrito somente para informações benéficas (desconto, destaque do link que o cliente deve acessar e etc) / Utilizou palavras de baixo calão, tom irônico, ríspido, demonstrou ausência de atenção total e/ou impaciência.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Agiu de acordo com o processo de atendimento PJ', 'Respondeu o e-mail direcionado a célula PJ de forma correta preenchendo somente os campos que são necessários para alertar a equipe que há uma solicitação a ser tratada (Anotação Interna)', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro do atendimento', 'Não registrou o atendimento (Criou caso)', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ortografia e concordância verbal', 'Escreveu nomes próprios com letra maiúscula e/ou minúscula / Não teve atenção à forma correta da escrita das palavras / Concordância: verbal e etc', NULL, 1, 8);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Objetividade resolutiva no primeiro contato', 'Utilizou a resposta padrão mais adequada à pergunta. Caso não seja possível utilizá-la, elaborou texto simples e claro, de acordo com a solicitação do cliente e que evite rechamadas / Buscou sanar ao máximo todas as dúvidas do cliente já na primeira resposta.', NULL, 1, 9);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão do atendimento (Indisponibilidade)', 'Não atendeu a necessidade do cliente / Encerrou a interação sem finalizar o atendimento / Não atendeu ao cliente / Não prestou o atendimento, quando tinha acesso as informações e etc', NULL, 1, 10);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Classificação do ticket de atendimento', 'Não classificou o ticket do atendimento de forma completa e correta.', NULL, 1, 11);
