INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Prontidão', 'Avaliar se o operador iniciou o atendimento em até 10 segundos, se houver pausa desconsidere.', 6.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação Inicial', 'Se apresentou em nome da instituição.', 2.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Personalização', 'Avaliar se o operador usou nome do cliente (mín. 2x) Uso de “você”.', 1.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Vícios de Linguagem / Português', 'Avaliar clareza, ausência de erros, vícios e gírias( então, aí, ok, ta bom, tá certo, oh)', 10.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Dicção / Tom de Voz', 'Clareza e adequação (inferir pela transcrição)', 8.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Empatia', 'Demonstra acolhimento e respeito', 5.00, 0, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Condução / Escuta Ativa', 'Não interrompe / compreende corretamente', 1.00, 0, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação Final', 'Encerramento cordial e adequado', 2.00, 0, 8);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Desenvolvimento (peso 5)', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Comunicação de Ausência', 'Informou pausas / não deixou silêncio indevido - acima de 60s', 1.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Domínio e Segurança', 'Segurança nas informações (sem “acho”, “talvez”)', 1.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cadastro', 'Validou/atualizou dados quando necessário', 2.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Autoatendimento', 'Informou canais quando aplicável', 1.00, 0, 4);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Negociação (peso 60)', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Abordagem', 'Motivo do contato claro Valores + débitos + data Uso de gatilho de oportunidade', 12.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Sondagem', 'Perguntas abertas Entendimento do cenário', 12.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Argumentação', 'Benefícios claros Uso do discurso do cliente', 12.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Contorno de Objeção', 'Mínimo 3 contornos (se houver objeção) Coerência e não robotização', 12.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Fechamento', 'Consequências do não pagamento Clareza no acordo ou encerramento - reforçando o pagamento na data acordada, evitando quebra do acordo acréscimo de juros, multas, negativação', 12.00, 0, 5);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'NCG', 'Erro crítico - zera o formulário', 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações erradas', 'Informações erradas', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas com impacto', 'Informações incompletas com impacto', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Acordo sem confirmação', 'Fechou acordo sem o aceite do aluno', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Falha ou ausência de registro (tabulação)', 'Não registrou o atendimento na ferramenta', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Quebra de sigilo (LGPD)', 'Passou informações sem confirmações de dados faculdade Estácio, Cruzeiro do Sul, Anima.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Mau atendimento', 'grosseria, ironia, agressividade', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Derrubada de ligação', 'Desligar a ligação.', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão de atendimento', 'Iniciou o atendimento em tempo superior a 20 segundos após a entrada da chamada. Segurou a ligação sem justificativa após recado da operadora ou caixa postal. Abandonou a ligação enquanto prestava o atendimento sem motivo. (Ex.: Caso o agente permaneça em linha após identificar que a chamada está muda caracteriza-se como omissão de atendimento).', NULL, 1, 8);
