INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Realizou o processo de forma correta e completa', 'Realizou o processo de forma correta e completa, de acordo com a solicitação do cliente.', 90.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cometeu erros de digitação na troca de e-mails', 'Cometeu erros de digitação na troca de e-mails', 10.00, 0, 2);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Erros Críticos (NCG)', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Agendamento de acordo com o solicitado', 'Verificou no SOC se o agendamento está de acordo com a solicitação do cliente.', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Agendamento correto', 'Organizou e realizou os agendamentos seguindo a priorização das datas, conforme as solicitações recebidas via caixa de entrada.', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ausência de link', 'Tratou inconsistências na geração de links de marcação, realizando a validação e inserção manual dos e-mails do cliente e do profissional no SOC, para envio manual do link.', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Agendamento (link colado)', 'Colou o link da consulta no campo detalhes no SOC', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Reserva atualizada', 'Verificou histórico (nome cliente) no e-mail, para rastrear intenções de agendamento antigos e alterar para a nova intenção', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Demonstrou cordialidade na troca de e-mails', 'Foi ríspido (aumentou o tamanho da letra ao repetir uma informação por exemplo) / Utilizou palavras de baixo calão, tom irônico, ríspido, demonstrou ausência de atenção total e/ou impaciência.', NULL, 1, 6);
