INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Empatia e Relacionamento com o Cliente', NULL, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação inicial', 'Se identificou com nome e sobrenome; nome da empresa e do produto. / Contém: cumprimento e apresentação, depois o texto da LGPD e por fim, se coloca à disposição para ajudar.', 15.00, 0, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Objetividade', 'Conduziu o atendimento com clareza, precisão e com linguagem apropriada e consistente, fazendo-se compreender com facilidade.', 15.00, 0, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Personalizou o atendimento', 'Chamou o cliente pelo nome no mínimo 3 vezes durante o atendimento', 15.00, 0, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Utilizou palavras de cortesia', 'Utilizou expressões de cordialidade durante a comunicação (obrigado(a), por gentileza, por favor e etc)', 10.00, 0, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Condução do atendimento', 'Conduziu, organizou e explicou corretamente as informações, garantindo clareza, coerência e alinhamento. / Editou a resposta pronta, excluindo informação ou acrescentando conforme a necessidade do cliente', 15.00, 0, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Atendimento pré-confirmação de consulta', 'Antes de enviar a mensagem de confirmação, confirmou se o cliente não fez alguma pergunta ou se há alguma interação sem resposta.', 10.00, 0, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Erros de digitação no registro', 'Cometeu erros de digitação no registro (concordância, pontuação e etc)', 10.00, 0, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Critério 1778863541168', 'Critério 1778863541168', 0.00, 0, 8);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Erros Críticos (NCG)', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cordialidade durante o diálogo', 'Utilizou a frase “como já havia dito anteriormente/acima”, "então". / Foi ríspido (aumentou o tamanho da letra ao repetir uma informação por exemplo). / Não utilizou o negrito somente para informações benéficas (desconto, destaque do link que o cliente deve acessar e etc). / Utilizou palavras de baixo calão, tom irônico, ríspido, demonstrou ausência de atenção total e/ou impaciência.', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Tabulação do atendimento', 'Não tabulou o atendimento e/ou tabulou de forma incorreta/incompleta', NULL, 1, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas/Incorretas', 'Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitir informações relevantes que podem prejudicar o cliente ou gerar uma novo contato. / Transmitiu informação equivocada ou que não conste em nossos documentos', NULL, 1, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Dados na planilha', 'Telefone ao lado do nome. / Agendado para o profissional correto. / Data e horário da sessão condizem com o que foi combinado com o cliente. / Nome de quem realizou o agendamento no campo de Obs.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Processo de atendimento', 'Identificou com o cliente se é a primeira vez que realiza a sessão, quando não fica claro durante a conversa. / Caso seja a primeira vez, informou o valor e a documentação necessária para que possa fazer seu cartão Sesi / Realizou pergunta de vínculo antes de passar valores / Respondeu a todos os questionamentos feitos pelo cliente / Deixou de transmitir informações relevantes que podem prejudicar o cliente.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão do atendimento (Indisponibilidade)', 'Não atendeu a necessidade do cliente / Encerrou a interação sem finalizar o atendimento / Não atendeu ao cliente / Não prestou o atendimento, quando tinha acesso as informações e etc', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação final', 'Reforçou com o cliente o dia, hora, nome do profissional, especialidade e endereço oficial Rua Santa Luzia 685 12º andar após o agendamento / Reforçou também o valor em caso de primeira sessão. / Nos casos de confirmação de consulta não é necessário utilizar a saudação final após a confirmação de comparecimento do cliente, colaborador se despede com a seguinte saudação: Equipe de Centro de Referência em Saúde agradece a sua atenção e deseja um excelente dia! Em caso de agendamento, finaliza com a seguinte fraseologia: “Sr(a) XXX Agendamento realizado para sua sessão de Shiatsu no dia xx/xx ás xx:xx. O valor da sessão é de R$ xx,xx. Não aceitamos pix. Lembramos que o CRS conta com uma equipe especializada e, em caso de imprevistos, poderá haver alteração de profissionais para garantir o seu atendimento.” Equipe de Centro de Referência em Saúde agradece a sua atenção e deseja um excelente dia!', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Ortografia e concordância verbal', 'Escreveu nomes próprios com letra maiúscula e/ou minúscula / Não teve atenção à forma correta da escrita das palavras / Concordância: verbal e etc / Gírias e vícios de Linguagem (tá, ok, né, hum-hum, no caso ou outras expressões repetidas) / Verbos no condicional (gostaria, seria, poderia), uso do diminutivo / Evitou termos técnicos que são de conhecimento interno (regimental, PFO, nomenclatura, módulos, comunidade) / Palavras ou expressões negativas (infelizmente, problema, dúvida, demora, etc.) / Gerundismo (vamos estar enviando, vou estar fazendo, vou estar registrando) / Pronúncia e concordância / Ausência ou acréscimo de palavras ou letras que não alterem o sentido da frase ou da palavra.', NULL, 1, 8);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Desmarcações e reagendamentos', 'Informou para o balcão em tempo real as desmarcações do mesmo dia e as do dia seguinte, para que possam tentar ocupar aqueles horários com outros clientes.', NULL, 1, 9);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro do atendimento', 'Não registrou o atendimento de forma completa e correta.', NULL, 1, 10);
INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Encerramento do atendimento', NULL, 3);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Utilizou saudação final', 'Utilizou fraseologia de finalização: A Firjan agradece, tenha um excelente e/ou ótimo dia/tarde/noite.', 10.00, 0, 1);
