INSERT INTO formulario_secoes (formulario_id, nome, descricao, posicao) VALUES (@formulario_id, 'Erros Críticos (NCG)', NULL, 2);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Encerramento por falta de interação', 'Encerrou o atendimento sem perguntar se o cliente deseja algo mais. / Não aguardou o tempo estipulado para retorno (3 minutos).', NULL, 1, 1);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação inicial', 'Não utilizou fraseologia inicial correta e completa com nome, sobrenome e empresa, depois o texto da LGPD.', NULL, 1, 2);
