INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Módulos de agendamento', 'Não reservou a quantidade de módulos correta para o tipo de consulta e especialidade.', NULL, 1, 4);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Dados na planilha', 'Telefone ao lado do nome. / Agendado para o profissional correto. / Data e horário da consulta condizem com o que foi combinado com o cliente. / Nome de quem realizou o agendamento no campo de OBS.', NULL, 1, 5);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Processo de atendimento - Informações incorretas e incompletas', 'Identificou com o cliente se é a primeira vez ou se já está em tratamento, quando não fica claro durante a conversa. / Em caso de consulta inicial, realiza pergunta de vínculo ou se possui Soberj para informar o valor de forma correta e a documentação necessária para que possa fazer seu cartão Sesi. / Ao realizar o agendamento de clientes que são cônjuges de industriários ou funcionários Firjan, orientar que devem apresentar na Unidade, além de seus documentos, a certidão de casamento ou declaração de união estável. / Responde a todos os questionamentos feitos pelo cliente. / Deixa de transmitir informações relevantes que podem prejudicar o cliente.', NULL, 1, 6);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Desmarcações e reagendamentos', 'As desmarcações do mesmo dia não devem ser retiradas da planilha, cliente deve ser mantido e no campo de observação deve ser informado que o cliente não comparecerá. / A equipe do balcão de atendimento deve ser informado em tempo real tanto nas desmarcações do mesmo dia quanto nas do dia seguinte, para que possam tentar ocupar aqueles horários com outros pacientes.', NULL, 1, 7);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Saudação final', 'Reforçou com o cliente o dia, hora, nome do profissional, especialidade e endereço correto após o agendamento. / Em caso de inicial, reforça também o valor. / Nos casos de confirmação de consulta não é necessário utilizar a saudação final após a confirmação de comparecimento do cliente (somente a localização com novo endereço em caso de alteração por algum motivo). / Finalizou atendimento com a seguinte saudação: Equipe de Centro de Referência em Saúde agradece a sua atenção e deseja um excelente dia!', NULL, 1, 8);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Cordialidade durante o diálogo', 'Utilizou a frase “como já havia dito anteriormente/acima”, "então". / Foi ríspido (aumentou o tamanho da letra ao repetir uma informação por exemplo). / Não utilizou o negrito somente para informações benéficas (desconto, destaque do link que o cliente deve acessar e etc). / Utilizou palavras de baixo calão, tom irônico, ríspido, demonstrou ausência de atenção total e/ou impaciência.', NULL, 1, 9);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Tabulação do atendimento', 'Não tabulou o atendimento e/ou tabulou de forma incorreta/incompleta', NULL, 1, 10);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Registro do atendimento', 'Não registrou o atendimento de forma completa e correta.', NULL, 1, 11);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Omissão do atendimento (Indisponibilidade)', 'Não atendeu a necessidade do cliente / Encerrou a interação sem finalizar o atendimento / Não atendeu ao cliente / Não prestou o atendimento, quando tinha acesso as informações e etc', NULL, 1, 12);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Informações incompletas/Incorretas', 'Prestou o atendimento de forma superficial deixando de fazer pesquisas e transmitir informações relevantes que podem prejudicar o cliente ou gerar uma novo contato. / Transmitiu informação equivocada ou que não conste em nossos documentos', NULL, 1, 13);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Pesquisa de satisfação', 'Não orientou e/ou enviou a pesquisa de satisfação ao final do atendimento.', NULL, 1, 14);
INSERT INTO formulario_criterios (secao_id, nome, enunciado, peso_pts, eliminatoria, posicao) VALUES (@secao_id, 'Confirmação dos dados e atualização cadastral', 'Não confirmou e/ou solicitou os dados pessoais do cliente para registrar (endereço/e-mail/telefone) / Não registrou os dados em sistema de forma correta e completa.', NULL, 1, 15);
